        if (high[i] >= highPoint) // Usar >= para garantir que o pico seja capturado
        {
            BuyEntryBuffer[i] = high[i];
            // Definir TP e SL apenas para a compra
            TPBuffer[i] = high[i] + Tppoints * _Point;
            SLBuffer[i] = high[i] - Slpoints * _Point;
        }

        // Sinal de Venda
        if (low[i] <= lowPoint) // Usar <= para garantir que o vale seja capturado
        {
            SellEntryBuffer[i] = low[i];
            // Definir TP e SL apenas para a venda
