//+------------------------------------------------------------------+
double findHigh(int bars)
{
    // O loop deve começar do índice 0 (a barra mais antiga no histórico passado) até 'bars'-1
    double highest = 0.0;
    for (int i = 0; i < bars; i++)
    {
        // iHigh(Símbolo, Período, Shift): Shift 0 é a barra atual (não deve ser usada em cálculo histórico)
        // Para histórico, usamos iHigh(_Symbol, PERIOD_CURRENT, i) onde i = 0 é a barra mais recente (fechada)
        double high = iHigh(_Symbol, PERIOD_CURRENT, i); 
        if (high > highest) highest = high;
    }
    return highest;
